        with self.lock:
            now = time.time()
            self._remove_expired_locked(now)
            created = key not in self.entries
            expires_at = None if ttl is None else now + ttl
            old_entry = self.entries.get(key)
            self.entries[key] = {"value": value, "expires_at": expires_at}
